// <auto-generated/>

using System;
using CargoWise.Windows.UI;
using Enterprise.Core;
using Enterprise.Freight.Forwarding.Business;
using Enterprise.ZArchitecture.GUI;

namespace Enterprise.Freight.Forwarding.GUI
{
	public partial class BookingDetailsControl : ZUserControl
	{
		public BookingDetailsControl()
		{
			InitializeComponent();
			BookedShippingLineBoundOrgFindBox.ReadOnly = true;
		}

		#region Shipment

		protected ForwardingShipment Shipment
		{
			get { return (ForwardingShipment)DataSource; }
		}

		#endregion

		#region Bind

		protected override void OnCurrentDataItemChanging(EventArgs e)
		{
			base.OnCurrentDataItemChanging(e);
			if (Shipment != null)
			{
				Shipment.JS_TransportModeInfo.ValueChanged -= JS_TransportModeInfo_ValueChanged;
			}
		}

		protected override void OnCurrentDataItemChanged(EventArgs e)
		{
			base.OnCurrentDataItemChanged(e);
			if (Shipment != null)
			{
				Shipment.JS_TransportModeInfo.ValueChanged += JS_TransportModeInfo_ValueChanged;
			}
		}

		#endregion

		public override void SetDataBinding(object dataSource, string dataMember)
		{
			base.SetDataBinding(dataSource, dataMember);
			if (dataSource != null)
			{
				SetupSailingCaptions();
				SetControlsVisible();
			}
		}

		void JS_TransportModeInfo_ValueChanged(object sender, EventArgs e)
		{
			SetupSailingCaptions();
			SetControlsVisible();
		}

		void SetupSailingCaptions()
		{
			if (Shipment == null)
			{
				return;
			}

			var journeySummary = Res.GetString("BookingDetailsControl|SailingSummarygroupBox.JourneySummary", "Journey Summary");
			JS_Calc_LCLCutOffBoundReadOnlyDateEdit.GetExtension<LabelCaptionRenderer>().Caption = Res.GetString("BookingDetailsControl|CutOffLabel.CFSCutOff", "CFS Cut Off");
			if (Shipment.IsSea)
			{
				VoyageNumberBoundTextBox.GetExtension<LabelCaptionRenderer>().Caption = Res.GetString("BookingDetailsControl|VoyageLabel.Voyage", "Voyage No");
				SailingSummarygroupBox.Text = Res.GetString("BookingDetailsControl|SailingSummarygroupBox.SailingSummary", "Sailing Summary");
			}
			else if (Shipment.IsAir)
			{
				VoyageNumberBoundTextBox.GetExtension<LabelCaptionRenderer>().Caption = Res.GetString("BookingDetailsControl|VoyageLabel.Flight", "Flight No");
				SailingSummarygroupBox.Text = Res.GetString("BookingDetailsControl|SailingSummarygroupBox.FlightSummary", "Flight Summary");
			}
			else if (Shipment.IsRail)
			{
				VoyageNumberBoundTextBox.GetExtension<LabelCaptionRenderer>().Caption = Res.GetString("BookingDetailsControl|VoyageLabel.Journey", "Journey");
				VesselBoundTextBox.GetExtension<LabelCaptionRenderer>().Caption = Res.GetString("BookingDetailsControl|VesselLabel.Journey", "Journey");
				SailingSummarygroupBox.Text = journeySummary;
			}
			else if (Shipment.IsRoad)
			{
				VoyageNumberBoundTextBox.GetExtension<LabelCaptionRenderer>().Caption = Res.GetString("BookingDetailsControl|VoyageLabel.TruckRef", "Truck Ref.");
				SailingSummarygroupBox.Text = journeySummary;
			}
		}

		void SetControlsVisible()
		{
			switch (Shipment.JS_PackingMode)
			{
				case Constants.ContainerModes.FCL:
				case Constants.ContainerModes.LCL:
					BookedShippingLineBoundOrgFindBox.Visible = true;
					BookingRefTextBox.Visible = true;
					SailingTotalVolumeCalcDropEdit.Visible = false;
					SailingTotalWeightCalcDropEdit.Visible = false;
					break;

				case Constants.ContainerModes.RollOnRollOff:
				case Constants.ContainerModes.Liquid:
				case Constants.ContainerModes.Bulk:
				case Constants.ContainerModes.BreakBulk:
					BookedShippingLineBoundOrgFindBox.Visible = false;
					BookingRefTextBox.Visible = false;
					SailingTotalVolumeCalcDropEdit.Visible = false;
					SailingTotalWeightCalcDropEdit.Visible = false;
					break;

				default:
					BookedShippingLineBoundOrgFindBox.Visible = false;
					BookingRefTextBox.Visible = false;
					SailingTotalVolumeCalcDropEdit.Visible = true;
					SailingTotalWeightCalcDropEdit.Visible = true;
					break;
			}

			if (Shipment.IsSea || Shipment.IsRail)
			{
				VesselBoundTextBox.Visible = true;
				JS_Calc_FCLCutOffBoundReadOnlyDateEdit.Visible = true;
			}
			else if (Shipment.IsAir)
			{
				VesselBoundTextBox.Visible = false;
				JS_Calc_FCLCutOffBoundReadOnlyDateEdit.Visible = false;
			}
			else if (Shipment.IsRoad)
			{
				VesselBoundTextBox.Visible = false;
				JS_Calc_FCLCutOffBoundReadOnlyDateEdit.Visible = true;
			}
		}
	}
}
